import { useState } from 'react';
import { useMutation, useQuery, useQueryClient } from '@tanstack/react-query';
import { useSubmitOnce } from '../../forms/useSubmitOnce';
import { addHoliday, holidaysKey, listHolidays } from './api';

/** The sheet's holidays (by date) and a form to add one. A claim's due-by, fixed when it is created,
 *  counts its terms in business days, skipping weekends and these holidays. */
export function Holidays({ sheetId, user }: { sheetId: string; user: string }) {
  const queryClient = useQueryClient();
  const holidays = useQuery({ queryKey: holidaysKey(sheetId), queryFn: () => listHolidays(sheetId) });
  const [date, setDate] = useState('');

  const save = useMutation({
    mutationFn: (input: string) => addHoliday(sheetId, user, input),
    onSuccess: () => {
      setDate('');
      return queryClient.invalidateQueries({ queryKey: holidaysKey(sheetId) });
    },
  });

  const submitOnce = useSubmitOnce();

  return (
    <section>
      <h3>Holidays</h3>
      <form
        onSubmit={(e) => {
          e.preventDefault();
          const input = date;
          submitOnce(() => {
            save.reset();
            return save.mutateAsync(input);
          });
        }}
      >
        <input data-testid="holiday-date" placeholder="Date (yyyy-mm-dd)" value={date}
          onChange={(e) => {
            setDate(e.target.value);
            save.reset();
          }} />{' '}
        <button type="submit" data-testid="holiday-add" disabled={save.isPending}>
          Add holiday
        </button>
        {save.isError && (
          <span data-testid="holiday-error">A holiday needs a date not already on the list.</span>
        )}
      </form>
      <ul>
        {(holidays.data ?? []).map((h) => (
          <li key={h.date} data-testid={`holiday-row-${h.date}`}>
            {h.date}
          </li>
        ))}
      </ul>
    </section>
  );
}
import { useState } from 'react';
import { useMutation, useQuery, useQueryClient } from '@tanstack/react-query';
import { useSubmitOnce } from '../../forms/useSubmitOnce';
import { useSheetToday } from '../sheet/api';
import { changeSetting, listSettings, PERMISSION_STANDING, settingOn, settingsKey, SETTING_KEYS, UNDATED_KEYS } from './api';

/** The sheet's settings: each one's value in force on the sheet's today and a form that changes them.
 *  A field shows the value in force until it is edited; saving saves the fields entered (every field
 *  when none was), a dated one from its from-date (blank: the sheet's today). */
export function Settings({ sheetId, user }: { sheetId: string; user: string }) {
  const queryClient = useQueryClient();
  const settings = useQuery({ queryKey: settingsKey(sheetId), queryFn: () => listSettings(sheetId) });
  const today = useSheetToday(sheetId, user);
  const current = (key: string) => settingOn(settings.data, key, today) ?? '';
  const [form, setForm] = useState<Record<string, string>>({});
  const [froms, setFroms] = useState<Record<string, string>>({});

  const save = useMutation({
    mutationFn: async ({ values, from }: { values: Record<string, string>; from: Record<string, string> }) => {
      for (const [key, value] of Object.entries(values)) await changeSetting(sheetId, user, key, value, from[key] ?? '');
    },
    onSettled: () => queryClient.invalidateQueries({ queryKey: settingsKey(sheetId) }),
  });

  const submitOnce = useSubmitOnce();

  const enter = (key: string) => setForm((f) => (key in f ? f : { ...f, [key]: current(key) }));

  const change = (key: string, value: string) => {
    setForm((f) => ({ ...f, [key]: value }));
    save.reset();
  };

  // A from-date entered alone saves the value in force from it.
  const changeFrom = (key: string, from: string) => {
    enter(key);
    setFroms((f) => ({ ...f, [key]: from }));
    save.reset();
  };

  return (
    <section>
      <h3>Settings</h3>
      <form
        onSubmit={(e) => {
          e.preventDefault();
          const values = Object.keys(form).length > 0 ? form
            : Object.fromEntries(SETTING_KEYS.map((key) => [key, current(key)]));
          submitOnce(() => {
            save.reset();
            return save.mutateAsync({ values, from: froms }).then(() => { setForm({}); setFroms({}); });
          });
        }}
      >
        {SETTING_KEYS.map((key) => (
          <div key={key}>
            <label>
              {key === 'clerk-limit' ? 'Clerk limit' : key === 'cap' ? 'Cap' : key === 'floor' ? 'Floor' : key === 'late-pct' ? 'Late percent'
                : key === 'policy-date' ? 'Policy date' : key === 'period-numbering-from' ? 'Period numbering from'
                : key === 'entry-date' ? 'Entry date'
                : key === 'grace-days' ? 'Grace days'
                : key === 'proof-threshold' ? 'Proof threshold'
                : key === 'note-threshold' ? 'Note threshold'
                : key.startsWith('perm-') ? `Who may ${key.slice('perm-'.length)} (roles)`
                : key.startsWith('grace-') ? `Grace days for grade ${key.slice('grace-'.length)}`
                : key.startsWith('terms-') ? `Terms for grade ${key.slice('terms-'.length)} (business days)` : 'Terms (business days)'}{' '}
              <input data-testid={`setting-${key}`} value={form[key] ?? current(key)}
                placeholder={key === 'clerk-limit' ? 'No limit' : key === 'proof-threshold' || key === 'note-threshold' ? 'None' : key === 'cap' ? 'No cap' : key === 'policy-date' ? 'Today (yyyy-MM-dd)'
                  : key === 'period-numbering-from' || key === 'entry-date' ? 'Off (yyyy-MM-dd)' : key === 'grace-days' ? 'Off' : key.startsWith('grace-') ? 'None' : key.startsWith('terms-') ? "Sheet's terms"
                  : key.startsWith('perm-') ? PERMISSION_STANDING[key.slice('perm-'.length)] : undefined}
                onFocus={() => enter(key)} onChange={(e) => change(key, e.target.value)} />
            </label>{' '}
            {!UNDATED_KEYS.includes(key) && (
              <>
                <label>
                  from{' '}
                  <input type="date" data-testid={`setting-${key}-from`} value={froms[key] ?? ''}
                    onChange={(e) => changeFrom(key, e.target.value)} />
                </label>{' '}
              </>
            )}
            Now: <span data-testid={`setting-${key}-current`}>{current(key)}</span>
          </div>
        ))}
        <button type="submit" data-testid="settings-save" disabled={save.isPending}>
          Save settings
        </button>
        {save.isError && (
          <span data-testid="settings-error">
            The clerk limit, the cap, the proof threshold and the note threshold must be blank, and the floor given, as 0.00 or more with up to two decimals;
            the terms a whole number of days, and a grade's terms blank or a whole number of days; the late percent 0.00 or more with up to two decimals; the policy date, period numbering date and entry date blank or a date; the grace days and a grade's grace days blank or a whole number of days; a permission blank or a comma separated list of clerk and steward; a from-date blank or a date.
          </span>
        )}
      </form>
    </section>
  );
}
import { useQuery } from '@tanstack/react-query';
import { getJson, postJson } from '../../api/http';
import { sheetKey } from '../sheet/api';
import type { Late } from '../rates/api';
import { dueBy, type Claim } from '../claims/api';
import { gradeOn, listPeople, peopleKey } from '../people/api';

/** A value recorded for a sheet setting: its value as text ("" when blank), in force from its
 *  from-date (yyyy-MM-dd; null: from the beginning of time, and always for an undated key). A key
 *  may have several, one per from-date; a setting never set is not listed. */
export type Setting = { sheetId: string; key: string; value: string; from: string | null };
/** The role a user name has on the sheet; a name not listed is a clerk. */
export type Role = { sheetId: string; user: string; role: string };

/** The settings the screen offers: the clerk limit (two decimals; blank means no limit), the cap
 *  (two decimals; blank means none: the most a person's due-total can be), the
 *  floor (two decimals; the least a claim's live due can be) and the terms (whole days after its
 *  date by which a claim is due) and the late percent (two decimals; the share of an overdue claim's
 *  figure it gains for every full 30 days it is overdue) and the policy date (yyyy-MM-dd; blank means
 *  the sheet's today: a claim dated before it rounds half up, on or after it half to even) and the
 *  period numbering date (yyyy-MM-dd; blank means off: once the sheet's today is on or after it, a
 *  claim opened is numbered within its period, <period>-<n>, or X-<n> in no period). A grade's own terms
 *  (terms-<grade>; blank means the sheet's terms) fix the due-by of a claim added for a person of that
 *  grade on its date: its date plus those terms, kept when the terms or its date change later. The proof
 *  threshold (two decimals; blank means none): a claim whose due is above the one in force on its date
 *  cannot be settled or approved while it has no proofs. The note threshold (two decimals; blank means none):
 *  a claim whose due is above the one in force on its date cannot be opened with an empty note. The permission matrix (perm-<action>, a comma
 *  separated list of roles; blank means the standing rule, PERMISSION_STANDING): who may take each action.
 *  The entry date (yyyy-MM-dd; blank means off): while set, a new claim with a blank date (the claim form,
 *  the quick-add bar, a pasted line, a correction) takes it instead of the sheet's today.
 *  The grace days (whole days; blank means off): when the sheet's today changes, every open period whose
 *  to-date plus them is before the new today is closed. A grade's grace days (grace-<grade>, whole days;
 *  blank means none): a claim whose person's grade in force on its date has them in force on that date is
 *  overdue only once its due-by plus them is before the sheet's today, and its late charge's 30-day
 *  boundaries count from there; the due-by it shows is unchanged. */
export const SETTING_KEYS = ['clerk-limit', 'cap', 'floor', 'terms', 'terms-A', 'terms-B', 'terms-C', 'late-pct', 'policy-date',
  'period-numbering-from', 'entry-date', 'grace-days', 'grace-A', 'grace-B', 'grace-C', 'proof-threshold', 'note-threshold', 'perm-open', 'perm-settle', 'perm-void', 'perm-reassign', 'perm-close', 'perm-reopen'] as const;

/** The roles that may take each action of the permission matrix while its entry is blank. */
export const PERMISSION_STANDING: Record<string, string> = {
  open: 'clerk,steward', settle: 'clerk,steward', void: 'clerk,steward', close: 'clerk,steward',
  reassign: 'steward', reopen: 'steward',
};

/** A setting's value until it is first set. */
export const SETTING_DEFAULTS: Record<string, string> = { floor: '1.00', terms: '14', 'late-pct': '0.00' };

/** The settings that are not dated: every other one is saved from a from-date (blank: the sheet's today). */
export const UNDATED_KEYS: readonly string[] = ['policy-date', 'period-numbering-from', 'entry-date', 'grace-days', 'perm-open', 'perm-settle', 'perm-void',
  'perm-reassign', 'perm-close', 'perm-reopen'];

/** A dated setting's value in force on a date (yyyy-MM-dd). */
export type DatedOn = (date: string) => string;

/** A setting's value in force on a date (yyyy-MM-dd): the one with the latest from-date on or before
 *  it; else its starting value (SETTING_DEFAULTS), and none (undefined) for a key with none. */
export function settingOn(settings: Setting[] | undefined, key: string, date: string): string | undefined {
  let found: Setting | undefined;
  for (const s of settings ?? []) {
    if (s.key !== key || (s.from !== null && s.from > date)) continue;
    if (found === undefined || (found.from ?? '') < (s.from ?? '')) found = s;
  }
  return found === undefined ? SETTING_DEFAULTS[key] : found.value;
}

const base = (sheetId: string) => `/api/sheets/${encodeURIComponent(sheetId)}`;

export const settingsKey = (sheetId: string) => [...sheetKey(sheetId), 'settings'] as const;
export const rolesKey = (sheetId: string) => [...sheetKey(sheetId), 'roles'] as const;

export function listSettings(sheetId: string): Promise<Setting[]> {
  return getJson<Setting[]>(`${base(sheetId)}/settings`);
}

/** Change a setting; refused (rejects) when the value is not valid for it. */
export function changeSetting(sheetId: string, by: string, key: string, value: string, from: string): Promise<Setting> {
  return postJson<Setting>(`${base(sheetId)}/settings?by=${encodeURIComponent(by)}`, { key, value, from });
}

export function listRoles(sheetId: string): Promise<Role[]> {
  return getJson<Role[]>(`${base(sheetId)}/roles`);
}

/** Assign a user name a role; refused (rejects) when the role is not clerk or steward. */
export function setRole(sheetId: string, by: string, user: string, role: string): Promise<Role> {
  return postJson<Role>(`${base(sheetId)}/roles?by=${encodeURIComponent(by)}`, { user, role });
}

/** The sheet's floor by date: the least a claim's live due can be, the one in force on its date. */
export function useFloor(sheetId: string): DatedOn {
  const settings = useQuery({ queryKey: settingsKey(sheetId), queryFn: () => listSettings(sheetId) });
  return (date) => settingOn(settings.data, 'floor', date) || SETTING_DEFAULTS.floor;
}

/** The sheet's proof threshold by date (null: none in force on that date). */
export function useProofThreshold(sheetId: string): (date: string) => string | null {
  const settings = useQuery({ queryKey: settingsKey(sheetId), queryFn: () => listSettings(sheetId) });
  return (date) => settingOn(settings.data, 'proof-threshold', date) || null;
}

/** The sheet's note threshold by date (null: none in force on that date). */
export function useNoteThreshold(sheetId: string): (date: string) => string | null {
  const settings = useQuery({ queryKey: settingsKey(sheetId), queryFn: () => listSettings(sheetId) });
  return (date) => settingOn(settings.data, 'note-threshold', date) || null;
}

/** The sheet's cap in force on its today: the most a person's due-total can be; null when there is none. */
export function useCap(sheetId: string, today: string): string | null {
  const settings = useQuery({ queryKey: settingsKey(sheetId), queryFn: () => listSettings(sheetId) });
  return settingOn(settings.data, 'cap', today) || null;
}

/** What a claim's late charge and rounding go by: the sheet's late percent by date (a late charge goes
 *  by the one in force on each 30-day boundary), today and policy date (its today when blank), and the
 *  date a claim's lateness counts from: its due-by plus the grace days (grace-<grade>) of its person's
 *  grade in force on its date, as in force on that date (blank: none). */
export function useLate(sheetId: string, today: string): Late {
  const settings = useQuery({ queryKey: settingsKey(sheetId), queryFn: () => listSettings(sheetId) });
